INSERT INTO public.riscos_biblioteca (codigo, titulo, descricao, categoria, causas, consequencias, probabilidade_sugerida, impacto_sugerido, tipos_ativo, controlos_recomendados, origem, tags) VALUES
('BIB-TEC-01','Ausência de solução de EDR/XDR nos postos e servidores','A proteção limita-se a um antivírus tradicional baseado em assinaturas, sem deteção comportamental, sem isolamento remoto do equipamento nem visibilidade centralizada.','Tecnologico',ARRAY['Custo da solução considerado elevado','Perceção de que o antivírus incluído no sistema operativo é suficiente','Ausência de equipa para operar alertas'],ARRAY['Malware moderno não detetado durante semanas','Impossibilidade de conter um equipamento comprometido a tempo','Investigação forense sem dados históricos'],4,5,ARRAY['estacao de trabalho','portatil','servidor'],ARRAY['A.8.7','A.8.16','A.5.24','A.8.15'],'ISO 27001',ARRAY['edr','malware','detecao']),
('BIB-TEC-02','Inexistência de firewall dedicado na fronteira da rede','A ligação à internet é assegurada apenas pelo router do operador, sem regras de filtragem, sem segmentação e sem inspeção de tráfego.','Tecnologico',ARRAY['Infraestrutura montada de forma incremental','Ausência de competências de rede internas'],ARRAY['Exposição direta de serviços internos à internet','Movimentação lateral sem obstáculos após uma intrusão'],4,5,ARRAY['rede/firewall','servidor'],ARRAY['A.8.20','A.8.21','A.8.22','A.8.16'],'ISO 27001',ARRAY['rede','firewall']),
('BIB-TEC-03','Rede interna sem segmentação','Servidores, postos de trabalho, impressoras, câmaras e a rede de visitantes partilham o mesmo segmento, sem qualquer separação.','Tecnologico',ARRAY['Rede plana herdada','Falta de equipamento com suporte a VLAN'],ARRAY['Propagação imediata de ransomware a toda a organização','Dispositivos pouco seguros usados como ponto de entrada'],4,5,ARRAY['rede/firewall','servidor','estacao de trabalho'],ARRAY['A.8.22','A.8.20','A.8.21'],'ISO 27001',ARRAY['rede','segmentacao']),
('BIB-TEC-04','Ausência de política de cópias de seguranca 3-2-1','As cópias existem apenas num disco ligado ao servidor, sem segunda cópia noutro suporte, sem cópia fora das instalações e sem cópia imutável.','Tecnologico',ARRAY['Solução de cópias improvisada','Custo do armazenamento externo','Ausência de responsável pelo processo'],ARRAY['Ransomware cifra dados e cópias em simultâneo','Perda definitiva de informação após avaria ou incêndio'],4,5,ARRAY['servidor','NAS/armazenamento','cloud/SaaS'],ARRAY['A.8.13','A.5.29','A.8.14','A.7.4'],'ISO 27001',ARRAY['backup','ransomware']),
('BIB-TEC-05','Restauro de cópias de seguranca nunca testado','As cópias são executadas mas nunca foi validado se é possível restaurar os dados e em quanto tempo.','Tecnologico',ARRAY['Falta de plano de testes periódicos','Ambiente de teste inexistente'],ARRAY['Descoberta da inutilidade das cópias apenas durante um incidente','Tempo de recuperação muito superior ao aceitável'],4,5,ARRAY['servidor','NAS/armazenamento'],ARRAY['A.8.13','A.5.30','A.8.14'],'ISO 27001',ARRAY['backup','continuidade']),
('BIB-TEC-06','NAS sem redundância nem cópia imutável','O armazenamento em rede que concentra os ficheiros da organização não tem redundância de discos adequada nem instantâneos protegidos contra escrita.','Tecnologico',ARRAY['Equipamento de gama doméstica','Configuração por omissão nunca revista','Firmware desatualizado'],ARRAY['Perda total dos ficheiros partilhados por falha de disco','Cifra dos ficheiros e dos instantâneos por ransomware'],4,5,ARRAY['NAS/armazenamento'],ARRAY['A.8.13','A.8.14','A.8.9','A.8.8'],'ISO 27001',ARRAY['nas','armazenamento','backup']),
('BIB-TEC-07','Ransomware com cifra de servidores e paragem da atividade','Um ataque de ransomware cifra servidores e partilhas de ficheiros, com exfiltração prévia de dados e pedido de resgate sob ameaça de divulgação.','Tecnologico',ARRAY['Acesso remoto exposto sem autenticação forte','Falhas de segurança por corrigir','Ausência de deteção comportamental'],ARRAY['Paragem total das operações durante dias','Divulgação pública de dados de clientes e colaboradores','Custos de recuperação e notificação às autoridades'],4,5,ARRAY['servidor','NAS/armazenamento','estacao de trabalho'],ARRAY['A.8.7','A.8.13','A.8.8','A.5.24','A.8.16','A.8.22'],'Ambos',ARRAY['ransomware','malware']),
('BIB-TEC-08','Contas funcionais e partilhadas sem responsável','Existem contas genéricas usadas por várias pessoas, incluindo em sistemas críticos, sem responsável designado nem rotação de palavra-passe.','Tecnologico',ARRAY['Práticas herdadas de simplificação operacional','Aplicações antigas sem suporte a contas individuais','Custo de licenças por utilizador'],ARRAY['Impossibilidade de imputar ações a uma pessoa','Palavra-passe conhecida por ex-colaboradores','Registos de auditoria sem valor probatório'],4,4,ARRAY['servidor','aplicacao web','base de dados'],ARRAY['A.5.16','A.5.17','A.8.2','A.8.15'],'ISO 27001',ARRAY['identidade','contas partilhadas']),
('BIB-TEC-09','Acesso privilegiado excessivo e permanente','Vários utilizadores têm permissões de administrador de forma permanente, incluindo nas suas contas de trabalho diário.','Tecnologico',ARRAY['Atribuição de privilégios para resolver problemas pontuais','Ausência de contas administrativas separadas','Falta de revisão periódica de acessos'],ARRAY['Comprometimento de um posto resulta em domínio total','Alterações não autorizadas sem rasto','Escalonamento imediato em ataques de phishing'],4,5,ARRAY['servidor','estacao de trabalho','cloud/SaaS'],ARRAY['A.8.2','A.5.15','A.5.18','A.8.18'],'ISO 27001',ARRAY['privilegios','iam']),
('BIB-TEC-10','Revisão periódica de acessos inexistente','Os direitos de acesso atribuídos nunca são revistos, acumulando-se ao longo das mudanças de função dos utilizadores.','Tecnologico',ARRAY['Ausência de processo de revisão','Falta de inventário de aplicações e de perfis'],ARRAY['Acumulação de permissões incompatíveis','Acessos ativos de pessoas que já saíram'],4,4,ARRAY['aplicacao web','cloud/SaaS','servidor'],ARRAY['A.5.18','A.5.15','A.5.16'],'ISO 27001',ARRAY['acessos','revisao']),
('BIB-TEC-11','Autenticação multifator não implementada','O acesso ao correio eletrónico, à VPN e a serviços na nuvem depende apenas de utilizador e palavra-passe.','Tecnologico',ARRAY['Resistência dos utilizadores','Serviços legados sem suporte','Configuração nunca ativada'],ARRAY['Tomada de conta a partir de credenciais roubadas','Acesso remoto não autorizado a dados da organização'],5,5,ARRAY['cloud/SaaS','aplicacao web','rede/firewall'],ARRAY['A.8.5','A.5.17','A.8.2'],'ISO 27001',ARRAY['mfa','autenticacao']),
('BIB-TEC-12','Palavras-passe fracas e reutilizadas','Não existem requisitos mínimos de complexidade nem gestor de palavras-passe, sendo comum a reutilização das mesmas credenciais em vários serviços.','Tecnologico',ARRAY['Política de palavras-passe inexistente','Ausência de gestor de palavras-passe corporativo'],ARRAY['Sucesso de ataques automáticos de tentativa de credenciais','Comprometimento em cadeia de vários serviços'],5,4,ARRAY['pessoas','cloud/SaaS','aplicacao web'],ARRAY['A.5.17','A.8.5','A.6.3'],'ISO 27001',ARRAY['credenciais']),
('BIB-TEC-13','Ausência de gestão de vulnerabilidades','Não são realizadas análises de vulnerabilidades e não existe processo para priorizar e corrigir as falhas encontradas.','Tecnologico',ARRAY['Ferramenta de análise inexistente','Falta de responsável e de janela de manutenção'],ARRAY['Exploração de falhas conhecidas com correção disponível há meses','Exposição continuada de serviços críticos'],5,4,ARRAY['servidor','aplicacao web','rede/firewall','estacao de trabalho'],ARRAY['A.8.8','A.8.9','A.8.32','A.8.19'],'ISO 27001',ARRAY['vulnerabilidades','patching']),
('BIB-TEC-14','Sistemas sem atualizações de segurança','Servidores, postos e equipamentos de rede permanecem sem atualizações de segurança durante longos períodos, alguns em versões já sem suporte.','Tecnologico',ARRAY['Receio de indisponibilidade ao atualizar','Dependência de software antigo','Ausência de gestão centralizada de atualizações'],ARRAY['Comprometimento por exploração de falha pública','Impossibilidade de obter correções para sistemas em fim de vida'],5,4,ARRAY['servidor','estacao de trabalho','rede/firewall'],ARRAY['A.8.8','A.8.19','A.8.32'],'ISO 27001',ARRAY['patching','obsolescencia']),
('BIB-TEC-15','Registos de eventos inexistentes ou não conservados','Os sistemas críticos não geram registos ou os registos são apagados ao fim de poucos dias, e ninguém os consulta.','Tecnologico',ARRAY['Registos desativados por omissão','Falta de espaço de armazenamento','Ausência de recolha centralizada'],ARRAY['Impossibilidade de reconstituir um incidente','Deteção nula de acessos indevidos','Dificuldade em cumprir obrigações de prova'],4,4,ARRAY['servidor','aplicacao web','base de dados','rede/firewall'],ARRAY['A.8.15','A.8.16','A.8.17','A.5.28'],'ISO 27001',ARRAY['logs','monitorizacao']),
('BIB-TEC-16','Ausência de monitorização e de alertas de segurança','Mesmo quando existem registos, não há alertas configurados nem alguém responsável por os analisar dentro de um prazo útil.','Tecnologico',ARRAY['Inexistência de SIEM ou de serviço gerido','Equipa reduzida sem turno de vigilância'],ARRAY['Intrusões prolongadas sem deteção','Fuga de dados descoberta por terceiros'],4,4,ARRAY['servidor','rede/firewall','cloud/SaaS'],ARRAY['A.8.16','A.8.15','A.5.24'],'ISO 27001',ARRAY['monitorizacao','siem']),
('BIB-TEC-17','Acesso remoto exposto sem proteção adequada','Serviços de administração remota estão acessíveis a partir da internet sem VPN, sem restrição de origem e sem autenticação forte.','Tecnologico',ARRAY['Necessidade de acesso rápido fora do horário','Configuração temporária tornada permanente'],ARRAY['Tentativas automáticas de acesso permanentes','Entrada direta de atacantes na rede interna'],5,5,ARRAY['servidor','rede/firewall'],ARRAY['A.8.20','A.8.5','A.8.21','A.8.16'],'ISO 27001',ARRAY['acesso remoto','rdp']),
('BIB-TEC-18','Dados sensíveis sem encriptação em repouso','Bases de dados, partilhas de ficheiros e cópias de seguranca guardam dados pessoais e comerciais sem qualquer cifra.','Tecnologico',ARRAY['Cifra não ativada na configuração inicial','Ausência de gestão de chaves'],ARRAY['Leitura direta dos dados em caso de furto de suportes','Agravamento das consequências de uma violação de dados'],3,5,ARRAY['base de dados','NAS/armazenamento','servidor'],ARRAY['A.8.24','A.8.12','A.5.33'],'Ambos',ARRAY['cifra','dados']),
('BIB-TEC-19','Comunicações sem proteção criptográfica','Serviços internos e transferências de ficheiros com parceiros utilizam protocolos sem cifra, expondo credenciais e conteúdos.','Tecnologico',ARRAY['Protocolos antigos ainda em utilização','Certificados inexistentes ou expirados'],ARRAY['Interceção de credenciais na rede','Alteração de dados em trânsito'],3,4,ARRAY['aplicacao web','rede/firewall','fornecedor'],ARRAY['A.8.24','A.5.14','A.8.21'],'ISO 27001',ARRAY['cifra','tls']),
('BIB-TEC-20','Gestão de chaves criptográficas deficiente','Chaves e certificados são guardados em ficheiros partilhados, sem controlo de acesso, sem rotação e sem registo de validade.','Tecnologico',ARRAY['Ausência de cofre de segredos','Falta de procedimento de rotação'],ARRAY['Expiração inesperada de certificados com paragem de serviços','Comprometimento da cifra por chave divulgada'],3,4,ARRAY['servidor','aplicacao web','cloud/SaaS'],ARRAY['A.8.24','A.5.33','A.8.2'],'ISO 27001',ARRAY['chaves','pki']),
('BIB-TEC-21','Dispositivos móveis pessoais sem gestão','Telemóveis pessoais acedem ao correio eletrónico e a documentos da organização sem código de acesso obrigatório, cifra ou possibilidade de apagamento remoto.','Tecnologico',ARRAY['Ausência de solução de gestão de dispositivos móveis','Política de dispositivos pessoais inexistente'],ARRAY['Perda ou furto de telemóvel com acesso ao correio','Impossibilidade de remover dados após a saída do colaborador'],4,3,ARRAY['dispositivo movel'],ARRAY['A.8.1','A.7.9','A.6.7','A.5.14'],'Ambos',ARRAY['mdm','byod']),
('BIB-TEC-22','Portátil perdido ou furtado sem cifra do disco','Os portáteis não têm cifra de disco ativada, pelo que a perda do equipamento significa a perda do controlo sobre toda a informação nele guardada.','Tecnologico',ARRAY['Cifra não ativada na preparação do equipamento','Ausência de verificação central do estado da cifra'],ARRAY['Acesso integral aos ficheiros por quem encontrar o equipamento','Violação de dados pessoais com notificação obrigatória'],3,5,ARRAY['portatil'],ARRAY['A.8.1','A.8.24','A.7.9','A.5.26'],'Ambos',ARRAY['cifra','portateis']),
('BIB-TEC-23','Ambientes de desenvolvimento e produção não separados','Alterações são testadas diretamente em produção e dados reais são copiados para ambientes de teste sem anonimização.','Tecnologico',ARRAY['Falta de infraestrutura para ambientes distintos','Pressão de prazos'],ARRAY['Indisponibilidade provocada por alterações mal testadas','Exposição de dados pessoais a programadores e a terceiros'],3,4,ARRAY['aplicacao web','base de dados','servidor'],ARRAY['A.8.31','A.8.33','A.8.32'],'Ambos',ARRAY['sdlc','ambientes']),
('BIB-TEC-24','Ausência de gestão de alterações','Alterações em sistemas e configurações são efetuadas sem pedido, sem aprovação, sem teste e sem plano de reversão.','Tecnologico',ARRAY['Equipa pequena com confiança informal','Inexistência de ferramenta de registo de alterações'],ARRAY['Indisponibilidade por alteração não avaliada','Impossibilidade de identificar a causa de uma falha'],4,3,ARRAY['servidor','aplicacao web','rede/firewall'],ARRAY['A.8.32','A.8.9','A.8.15'],'ISO 27001',ARRAY['mudancas']),
('BIB-TEC-25','Configurações inseguras por omissão','Sistemas e equipamentos permanecem com credenciais e serviços de fábrica, sem qualquer processo de reforço de configuração.','Tecnologico',ARRAY['Instalações rápidas sem checklist','Ausência de linhas de base de configuração'],ARRAY['Acesso trivial através de credenciais conhecidas','Serviços desnecessários expostos'],4,4,ARRAY['servidor','rede/firewall','NAS/armazenamento'],ARRAY['A.8.9','A.8.8','A.8.20'],'ISO 27001',ARRAY['hardening']),
('BIB-TEC-26','Aplicação web vulnerável a ataques comuns','A aplicação exposta à internet não foi testada quanto a injeção, autenticação deficiente ou controlo de acesso, nem tem proteção aplicacional à frente.','Tecnologico',ARRAY['Desenvolvimento sem requisitos de segurança','Ausência de testes de intrusão','Dependências desatualizadas'],ARRAY['Extração da base de dados de clientes','Desfiguração do sítio e perda de reputação'],4,5,ARRAY['aplicacao web','base de dados'],ARRAY['A.8.25','A.8.26','A.8.28','A.8.29','A.8.8'],'Ambos',ARRAY['appsec','owasp']),
('BIB-TEC-27','Cópias e ficheiros na nuvem com partilhas públicas','Pastas e ligações de partilha em serviços na nuvem estão acessíveis a qualquer pessoa com o endereço, incluindo motores de busca.','Tecnologico',ARRAY['Partilhas criadas para facilitar o envio a terceiros','Ausência de revisão das partilhas ativas'],ARRAY['Divulgação pública de documentos internos e de dados pessoais','Descarregamento silencioso por terceiros'],4,4,ARRAY['cloud/SaaS'],ARRAY['A.5.14','A.8.3','A.5.23','A.8.12'],'Ambos',ARRAY['cloud','partilhas']),
('BIB-TEC-28','Ausência de prevenção de fuga de informação','Não existem mecanismos que detetem ou impeçam o envio de grandes volumes de dados sensíveis para fora da organização.','Tecnologico',ARRAY['Ferramenta de prevenção inexistente','Informação não classificada, impossibilitando regras'],ARRAY['Exfiltração de dados sem deteção','Descoberta da fuga apenas após publicação'],3,4,ARRAY['estacao de trabalho','cloud/SaaS','base de dados'],ARRAY['A.8.12','A.5.13','A.8.16'],'Ambos',ARRAY['dlp','fuga de dados']),
('BIB-TEC-29','Sobrecarga e indisponibilidade dos serviços expostos','Os serviços disponibilizados na internet não têm proteção contra ataques de negação de serviço nem monitorização de capacidade.','Tecnologico',ARRAY['Ausência de serviço de mitigação','Capacidade dimensionada sem margem'],ARRAY['Indisponibilidade do sítio e dos serviços a clientes','Incumprimento de níveis de serviço contratados'],3,4,ARRAY['aplicacao web','rede/firewall','cloud/SaaS'],ARRAY['A.8.6','A.8.16','A.5.30'],'ISO 27001',ARRAY['disponibilidade','ddos']),
('BIB-TEC-30','Comprometimento da cadeia de fornecimento de software','Componentes de terceiros, bibliotecas e ferramentas de gestão remota utilizados pela organização podem ser comprometidos na origem.','Tecnologico',ARRAY['Ausência de inventário de componentes','Atualizações automáticas sem verificação de integridade'],ARRAY['Introdução de código malicioso com privilégios elevados','Comprometimento simultâneo de vários sistemas'],3,5,ARRAY['servidor','aplicacao web','fornecedor'],ARRAY['A.5.21','A.8.30','A.8.28','A.8.8'],'ISO 27001',ARRAY['supply chain']),
('BIB-PRIV-01','Tratamento de dados pessoais sem base legal identificada','A organização trata dados pessoais de clientes, candidatos e colaboradores sem determinar e documentar a base de licitude aplicável a cada finalidade.','Privacidade',ARRAY['Ausência de análise de licitude por finalidade','Recolha de dados por hábito e não por necessidade'],ARRAY['Tratamento ilícito à luz do artigo 6 do RGPD','Coimas e ordens de cessação do tratamento pela CNPD'],4,5,ARRAY['base de dados','aplicacao web','pessoas'],ARRAY['A.5.34','A.5.31','A.5.36'],'RGPD',ARRAY['rgpd','base legal']),
('BIB-PRIV-02','Registo das atividades de tratamento inexistente ou desatualizado','Não existe registo das atividades de tratamento nos termos do artigo 30 do RGPD, ou o existente não reflete os tratamentos atuais.','Privacidade',ARRAY['Documento nunca elaborado','Novos tratamentos iniciados sem atualização do registo'],ARRAY['Impossibilidade de responder a um pedido da autoridade de controlo','Desconhecimento dos fluxos de dados pessoais'],4,4,ARRAY['pessoas','base de dados','cloud/SaaS'],ARRAY['A.5.34','A.5.31','A.5.9'],'RGPD',ARRAY['rgpd','ropa']),
('BIB-PRIV-03','Retenção indefinida de dados pessoais','Os dados pessoais são conservados indefinidamente, sem prazos definidos por finalidade e sem eliminação ou anonimização automática.','Privacidade',ARRAY['Política de retenção inexistente','Receio de apagar informação que possa vir a ser necessária','Sistemas sem funcionalidade de eliminação'],ARRAY['Violação do princípio da limitação da conservação','Aumento do impacto de qualquer violação de dados','Custos de armazenamento desnecessários'],5,4,ARRAY['base de dados','NAS/armazenamento','cloud/SaaS'],ARRAY['A.5.33','A.8.10','A.5.34'],'RGPD',ARRAY['rgpd','retencao']),
('BIB-PRIV-04','Incumprimento do prazo de 72 horas na notificação à CNPD','A organização não tem processo que assegure a avaliação e a notificação de uma violação de dados pessoais à autoridade de controlo no prazo legal.','Privacidade',ARRAY['Ausência de procedimento e de responsável designado','Deteção tardia dos incidentes','Desconhecimento dos critérios de notificação'],ARRAY['Incumprimento do artigo 33 do RGPD','Agravamento da coima por falta de cooperação','Perda de confiança dos titulares'],3,5,ARRAY['pessoas','base de dados'],ARRAY['A.5.26','A.5.24','A.5.25','A.6.8'],'RGPD',ARRAY['rgpd','notificacao','cnpd']),
('BIB-PRIV-05','Pedidos de exercício de direitos sem processo de resposta','Não existe canal nem procedimento para responder a pedidos de acesso, retificação, apagamento ou portabilidade dentro do prazo de um mês.','Privacidade',ARRAY['Pedidos recebidos em caixas de correio dispersas','Dificuldade em localizar todos os dados de um titular'],ARRAY['Resposta fora de prazo ou inexistente','Reclamações à autoridade de controlo'],4,3,ARRAY['pessoas','base de dados','aplicacao web'],ARRAY['A.5.34','A.5.31','A.8.10'],'RGPD',ARRAY['rgpd','direitos']),
('BIB-PRIV-06','Avaliação de impacto sobre a proteção de dados não realizada','Tratamentos de risco elevado, como videovigilância ou perfis automatizados, avançam sem avaliação de impacto nos termos do artigo 35.','Privacidade',ARRAY['Desconhecimento da obrigação','Ausência de critério de triagem de novos tratamentos'],ARRAY['Tratamentos de risco elevado sem medidas mitigadoras','Incumprimento detetado em fiscalização'],3,4,ARRAY['aplicacao web','instalacao fisica','base de dados'],ARRAY['A.5.34','A.5.8','A.5.31'],'RGPD',ARRAY['rgpd','aipd']),
('BIB-PRIV-07','Proteção de dados desde a conceção não aplicada','Novos sistemas e formulários são desenhados sem minimização de dados, sem definições de privacidade por omissão e sem prazos de eliminação.','Privacidade',ARRAY['Requisitos de privacidade ausentes nas especificações','Reutilização de modelos antigos'],ARRAY['Recolha de dados excessiva e desnecessária','Correções tardias e dispendiosas'],4,3,ARRAY['aplicacao web','base de dados'],ARRAY['A.5.8','A.8.25','A.5.34'],'RGPD',ARRAY['rgpd','privacy by design']),
('BIB-PRIV-08','Transferências internacionais de dados sem garantias adequadas','Dados pessoais são tratados por serviços alojados fora do Espaço Económico Europeu sem cláusulas contratuais-tipo nem avaliação de impacto da transferência.','Privacidade',ARRAY['Contratação de serviços na nuvem sem análise jurídica','Subcontratantes com infraestrutura fora da União Europeia'],ARRAY['Transferência ilícita nos termos do capítulo V do RGPD','Ordem de suspensão da transferência pela autoridade'],4,4,ARRAY['cloud/SaaS','fornecedor'],ARRAY['A.5.34','A.5.19','A.5.31','A.5.14'],'RGPD',ARRAY['rgpd','transferencias']),
('BIB-PRIV-09','Subcontratantes sem contrato nos termos do artigo 28','Prestadores que tratam dados pessoais por conta da organização não têm contrato escrito com as garantias exigidas pelo RGPD.','Privacidade',ARRAY['Serviços contratados sem anexo de proteção de dados','Subcontratação ulterior não autorizada'],ARRAY['Responsabilidade integral do responsável pelo tratamento','Ausência de obrigação de notificação por parte do prestador'],4,4,ARRAY['fornecedor','cloud/SaaS'],ARRAY['A.5.20','A.5.19','A.5.34'],'RGPD',ARRAY['rgpd','subcontratantes']),
('BIB-PRIV-10','Informação aos titulares insuficiente','Os avisos de privacidade estão desatualizados, são genéricos ou não são apresentados no momento da recolha dos dados.','Privacidade',ARRAY['Textos copiados de outras entidades','Novas finalidades não refletidas no aviso'],ARRAY['Incumprimento dos artigos 13 e 14 do RGPD','Consentimentos considerados inválidos'],4,3,ARRAY['aplicacao web','pessoas'],ARRAY['A.5.34','A.5.31'],'RGPD',ARRAY['rgpd','transparencia']),
('BIB-PRIV-11','Medidas de segurança do artigo 32 não demonstráveis','A organização não consegue demonstrar que as medidas técnicas e organizativas aplicadas são adequadas ao risco para os direitos dos titulares.','Privacidade',ARRAY['Medidas aplicadas sem documentação','Ausência de avaliação de risco orientada aos titulares'],ARRAY['Presunção de incumprimento em caso de violação','Agravamento das coimas aplicadas'],4,4,ARRAY['servidor','base de dados','cloud/SaaS'],ARRAY['A.5.34','A.8.24','A.8.13','A.5.36'],'Ambos',ARRAY['rgpd','artigo 32']),
